def norm_prov(s):
    """归属地字符串 → prov 短名 (中英通吃, 剥 行政区 后缀); 不匹配返回 None."""
    if not s:
        return None
    t = str(s).strip()
    for suf in _PROV_SUFFIX:
        if t.endswith(suf):
            t = t[:-len(suf)]
            break
    return t if t in _PROVS else PROV_ALIAS.get(t.lower())


def norm_city(s):
    """城市名剥 市/区 后缀 ('深圳市'→'深圳'), 对齐台表 city 锚点."""
    if not s:
        return None
    t = str(s).strip()
    for suf in ("市", "区"):
        if t.endswith(suf):
            t = t[:-len(suf)]
            break
    return t or None


def local_rank(st, prov, city):
    """本地置顶排序键: 0=同城 1=同省 2=其他 (配稳定排序, 保组内原序)."""
    if city and st.get("city") == city:
        return 0
    if prov and st.get("prov") == prov:
        return 1
    return 2
